SELECT COUNT(*) AS "count_result" FROM triples t0, triples t1, triples t2, triples t3, triples t4, triples t5 WHERE t0.p = 'http://purl.org/goodrelations/includes' AND t1.s = 'http://db.uwaterloo.ca/~galuc/wsdbm/Retailer685' AND t1.p = 'http://purl.org/goodrelations/offers' AND t1.o = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://purl.org/goodrelations/price' AND struct_pack(kind := 0::UTINYINT, value := t3.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t3.p = 'http://purl.org/goodrelations/validThrough' AND struct_pack(kind := 0::UTINYINT, value := t4.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = t0.o AND t4.p = 'http://ogp.me/ns#title' AND struct_pack(kind := 0::UTINYINT, value := t5.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = t0.o AND t5.p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type'